<template>
  <div class="qac-studio">
    <header class="qac-hero">
      <div class="qac-hero-copy"><span class="qac-eyebrow">QGAUSS AI / YOUR OWN SPACE</span><p class="qac-section-tag">{{ ct('个人空间') }}</p><h1>{{ ct('每一个灵感，') }}<br /><mark>{{ ct('都有你的名字。') }}</mark></h1><p>{{ ct('照顾好你的创作身份，再把好点子交给世界。') }}</p><div class="qac-hero-links"><button type="button" @click="openSection('profile')">{{ ct('编辑创作身份') }} <ClientIcon name="arrowUpRight" /></button><button type="button" @click="openSection('security')"><ClientIcon name="lock" /> {{ ct('登录与密码') }}</button></div></div>
      <div class="qac-pass-scene" :aria-label="ct('创作身份卡')"><span class="qac-pass-halo"></span><div class="qac-pass-flipper" :class="{'is-flipped':cardTurned}"><div class="qac-creator-pass"><div class="qac-pass-front" :aria-hidden="cardTurned"><span class="qac-pass-top">QGAUSS <b>CREATOR PASS</b></span><AccountAvatar :value="draft.avatar" :size="86" /><strong>{{ draft.displayName.trim() || profile?.displayName || auth.user?.username || ct('你的创作身份') }}</strong><p class="qac-pass-signature">{{ draft.signature.trim() || ct('给灵感，留一点你的语气。') }}</p><span class="qac-pass-role">{{ dirty ? ct('编辑预览 · 尚未保存') : profile?.role === 'ADMIN' ? ct('站点管理员') : ct('创作伙伴') }}</span><span class="qac-pass-cut"></span><div class="qac-pass-bottom"><span>IDEAS START WITH YOU</span><span aria-hidden="true">✦</span></div></div><div id="qac-pass-back" class="qac-pass-back" :aria-hidden="!cardTurned"><span class="qac-eyebrow">QGAUSS / A LINE OF MY OWN</span><strong>{{ct('一点关于我')}}</strong><p ref="signaturePreview" class="qac-pass-signature-full" :tabindex="cardTurned?0:-1">{{draft.signature.trim() || ct('留一句喜欢的话，让创作有自己的语气。')}}</p><span class="qac-pass-role">{{ct(dirty?'编辑预览 · 尚未保存':'你的创作，始终属于你。')}}</span></div></div></div><button type="button" class="qac-flip-toggle" :aria-pressed="cardTurned" aria-controls="qac-pass-back" @click="turnCard">{{ct(cardTurned?'返回创作卡正面':'翻看个人签名')}}<ClientIcon name="refresh" /></button><span class="qac-scene-orbit"></span><span class="qac-scene-star" aria-hidden="true">✦</span></div>
    </header>

    <nav ref="sectionNavigation" class="qac-tabs" :aria-label="ct('个人空间分区')" role="tablist"><button v-for="(tab,index) in sections" :id="'qac-tab-' + tab.id" :key="tab.id" :ref="el => tabButtons[index] = el" type="button" role="tab" :aria-selected="section === tab.id" :aria-controls="'qac-panel-' + tab.id" :tabindex="section === tab.id ? 0 : -1" @click="openSection(tab.id)" @keydown="tabKey($event,index)"><ClientIcon :name="tab.icon" /><span>{{ ct(tab.title) }}</span><b>{{ tab.number }}</b></button></nav>

    <div v-if="loading" class="qac-state" role="status"><BrandLoader /><h2>{{ ct('正在取回你的创作身份') }}</h2><p>{{ ct('资料准备好，就可以继续。') }}</p></div>
    <div v-else-if="ct(loadError)" class="qac-state" role="alert"><span class="qac-state-symbol">↻</span><h2>{{ ct('这次没有取回资料') }}</h2><p>{{ ct(loadError) }}</p><button class="qac-primary" type="button" @click="loadProfile">{{ ct('重新读取') }}</button></div>
    <template v-else-if="profile">
      <section v-show="section === 'profile'" id="qac-panel-profile" class="qac-panel qac-profile-grid" role="tabpanel" aria-labelledby="qac-tab-profile">
        <form class="qac-card qac-profile-form" @submit.prevent="saveProfile">
          <div class="qac-card-heading"><span class="qac-number">01</span><div><h2>{{ ct('和灵感打个招呼') }}</h2><p>{{ ct('这里的名字会出现在你的 QGauss 空间里。') }}</p></div></div>
          <label class="qac-label" for="qac-name">{{ ct('创作昵称') }} <span>{{ ct('最多 32 个字符') }}</span></label><input id="qac-name" v-model="draft.displayName" class="qac-input" maxlength="64" autocomplete="nickname" :placeholder="ct('你希望 QGauss 怎么称呼你？')" :disabled="profileSaving || sessionBusy" :aria-invalid="!!ct(nameProblem)" aria-describedby="qac-name-hint" /><p id="qac-name-hint" class="qac-field-hint" :class="{ 'is-error': ct(nameProblem) }">{{ ct(nameProblem) || ct('修改不会自动保存；邮箱与登录名保持原有设置。') }}</p><label class="qac-label" for="qac-signature">{{ ct('个人签名') }} <span>{{ [...draft.signature].length }} / 300</span></label><textarea id="qac-signature" v-model="draft.signature" class="qac-input qac-signature-input" maxlength="600" rows="3" :placeholder="ct('留下一句属于你的话，让灵感有自己的语气。')" :disabled="profileSaving || sessionBusy" :aria-invalid="!!ct(signatureProblem)" aria-describedby="qac-signature-hint"></textarea><p id="qac-signature-hint" class="qac-field-hint" :class="{'is-error':ct(signatureProblem)}">{{ ct(signatureProblem) || ct('最多 300 个字符，可留空。仅在你的个人空间展示。') }}</p>
          <fieldset class="qac-avatar-field" :disabled="profileSaving || sessionBusy || avatarBusy || avatarEditing"><legend>{{ ct('挑一位头像搭档') }}</legend><div class="qac-avatar-options"><button v-for="avatar in ACCOUNT_AVATARS" :key="avatar.id" type="button" :aria-label="ct(avatar.name)" :aria-pressed="draft.avatar === avatar.id" @click="draft.avatar = avatar.id; avatarTouched = true"><AccountAvatar :value="avatar.id" :size="48" decorative /><span>{{ ct(avatar.name) }}</span><b v-if="draft.avatar === avatar.id" aria-hidden="true">✓</b></button></div></fieldset>
          <ProfilePhotoPicker :model-value="draft.avatar" :disabled="profileSaving||sessionBusy||passwordSaving" @update:model-value="choosePhoto" @busy="avatarBusy=$event" @editing="avatarEditing=$event" @refresh="confirmProfile"/>
          <div v-if="ct(profileNote)" class="qac-inline-note" :class="{ 'is-error': profileNoteKind === 'error' }" role="status">{{ ct(profileNote) }}</div>
          <div class="qac-form-actions"><span>{{ profileUncertain ? ct('先确认保存结果，再继续编辑。') : dirty ? ct('有尚未保存的更改') : ct('资料已与当前账户同步') }}</span><button v-if="profileUncertain" type="button" class="qac-primary" :disabled="profileSaving || sessionBusy || avatarBusy || avatarEditing" @click="confirmProfile">{{ ct('读取最新资料') }}</button><button v-else type="submit" class="qac-primary" :disabled="!dirty || !!ct(nameProblem) || !!ct(signatureProblem) || profileSaving || sessionBusy || avatarBusy || avatarEditing"><span v-if="profileSaving" class="qac-spinner" aria-hidden="true"></span>{{ profileSaving ? ct('正在保存') : ct('保存创作身份') }}<ClientIcon v-if="!profileSaving" name="arrowUpRight" /></button></div>
        </form>
        <aside class="qac-card qac-account-facts"><span class="qac-eyebrow">BELONGS TO YOU</span><h2>{{ ct('你的账户名片') }}</h2><dl><div><dt>{{ ct('登录名') }}</dt><dd>{{ profile.username }}</dd></div><div><dt>{{ ct('注册邮箱') }}</dt><dd>{{ profile.email || ct('暂无记录') }}</dd></div><div><dt>{{ ct('加入时间') }}</dt><dd>{{ accountDate(profile.createdAt) }}</dd></div><div><dt>{{ ct('账户角色') }}</dt><dd>{{ profile.role === 'ADMIN' ? ct('站点管理员') : ct('普通用户') }}</dd></div></dl><p>{{ ct('个人空间仅供本人查看。需要调整登录邮箱或账户角色时，请联系站点管理员。') }}</p><button type="button" @click="openSection('security')">{{ ct('查看登录足迹') }} <ClientIcon name="arrowUpRight" /></button></aside>
      </section>

      <section v-show="section === 'security'" id="qac-panel-security" class="qac-panel qac-security-grid" role="tabpanel" aria-labelledby="qac-tab-security">
        <AccountSessionsCard :profile="profile" :blocked="profileSaving || passwordSaving" @busy="sessionBusy=$event" @profile-received="applyProfile($event,false)" />
        <EmailVerificationCard v-model:code="emailCode" :email="profile.email" :owner-key="profile.id" :verified-at="profile.emailVerifiedAt || ''" :delivery-ready="emailReady" :disabled="profileSaving || passwordSaving || sessionBusy" @verified="emailVerified" />
        <form class="qac-card qac-password-form" @submit.prevent="reviewPassword"><div class="qac-card-heading"><span class="qac-number">02</span><div><h2>{{ ct('给创作空间换把钥匙') }}</h2><p>{{ ct('修改后，此账号在所有设备的登录都会失效。') }}</p></div></div><router-link class="qac-recovery-link" to="/login?mode=forget&amp;redirect=/account">{{ ct('忘记当前密码？通过邮箱找回') }} <ClientIcon name="arrowUpRight" /></router-link><label class="qac-label" for="qac-old-password">{{ ct('当前密码') }}</label><input id="qac-old-password" v-model="password.old" class="qac-input" :type="showPasswords ? 'text' : 'password'" autocomplete="current-password" maxlength="128" :disabled="passwordSaving || sessionBusy" /><label class="qac-label" for="qac-new-password">{{ ct('新密码') }} <span>{{ profile.role === 'ADMIN' ? ct('12–32 字符，英文字母＋数字') : ct('8–32 个字符') }}</span></label><input id="qac-new-password" v-model="password.next" class="qac-input" :type="showPasswords ? 'text' : 'password'" autocomplete="new-password" maxlength="64" :disabled="passwordSaving || sessionBusy" /><label class="qac-label" for="qac-confirm-password">{{ ct('再填写一次新密码') }}</label><input id="qac-confirm-password" v-model="password.confirm" class="qac-input" :type="showPasswords ? 'text' : 'password'" autocomplete="new-password" maxlength="64" :disabled="passwordSaving || sessionBusy" /><label class="qac-check"><input v-model="showPasswords" type="checkbox" :disabled="passwordSaving || sessionBusy" /> {{ ct('显示密码') }}</label><p v-if="ct(passwordError)" class="qac-inline-note is-error" role="alert">{{ ct(passwordError) }}</p><div class="qac-form-actions"><span>{{ ct('密码不会保存在此浏览器的草稿中。') }}</span><button type="submit" class="qac-primary" :disabled="passwordSaving || sessionBusy">{{ ct('确认修改') }} <ClientIcon name="arrowUpRight" /></button></div></form>
        <div class="qac-card qac-login-history"><div class="qac-card-heading"><span class="qac-number">↗</span><div><h2>{{ ct('最近的登录足迹') }}</h2><p>{{ ct('设备名称由浏览器报告，不代表设备认证。') }}</p></div></div><div v-if="logsLoading" class="qac-history-state" role="status"><span class="qac-spinner"></span>{{ ct('正在读取登录记录') }}</div><div v-else-if="ct(logsError)" class="qac-history-state" role="alert"><p>{{ ct(logsError) }}</p><button type="button" @click="loadLogs(logPage)">{{ ct('重试读取') }}</button></div><div v-else-if="!loginRows.length" class="qac-history-state"><span>✦</span><p>{{ ct('暂时没有登录记录。') }}</p></div><ol v-else><li v-for="row in loginRows" :key="row.id"><span class="qac-login-icon"><ClientIcon name="user" /></span><div><strong>{{ loginDevice(row.userAgent) }}</strong><time :datetime="row.createdAt">{{ accountDate(row.createdAt) }}</time><small>{{ revealNetwork ? row.ip || ct('未记录网络地址') : ct('网络地址已隐藏') }}</small></div><span class="qac-login-outcome" :class="{ failed: !row.success }">{{ row.success ? ct('登录成功') : ct('未登录成功') }}</span></li></ol><div class="qac-history-tools"><button type="button" :aria-pressed="revealNetwork" @click="revealNetwork = !revealNetwork">{{ revealNetwork ? ct('隐藏网络地址') : ct('显示网络地址') }}</button><span>{{ logsLoading ? ct('正在读取记录') : ct(logsError) ? ct('记录数量尚未确认') : ct('{count} 条记录',{count:logTotal}) }}</span></div><nav v-if="logTotal > logPageSize" class="qac-pager" :aria-label="ct('登录记录分页')"><button type="button" :disabled="logsLoading || logPage <= 1" @click="loadLogs(logPage - 1)">{{ ct('上一页') }}</button><span>{{ct('第 {page} 页',{page:logPage})}}</span><button type="button" :disabled="logsLoading || logPage * logPageSize >= logTotal" @click="loadLogs(logPage + 1)">{{ ct('下一页') }}</button></nav></div>
      </section>

      <section v-show="section === 'start'" id="qac-panel-start" class="qac-panel qac-start-grid" role="tabpanel" aria-labelledby="qac-tab-start"><div class="qac-card qac-start-intro"><span class="qac-eyebrow">YOUR NEXT SMALL STEP</span><h2>{{ ct('从一个小念头，') }}<br /><mark>{{ ct('走到第一份作品。') }}</mark></h2><p>{{ ct('挑一个现在想做的事。这里只打开工作区，你准备好后再开始生成。') }}</p><div class="qac-start-orb" aria-hidden="true"><span>Q</span><i>✦</i></div></div><router-link v-for="step in startSteps" :key="step.path" class="qac-card qac-start-step" :to="step.path"><span class="qac-step-icon"><ClientIcon :name="step.icon" /></span><span><small>{{ step.number }}</small><h3>{{ ct(step.title) }}</h3><p>{{ ct(step.description) }}</p></span><ClientIcon name="arrowUpRight" /></router-link></section>
    </template>
    <dialog ref="passwordDialog" class="qac-confirm-dialog" aria-labelledby="qac-password-dialog-title" @cancel="cancelPasswordReview"><span class="qac-dialog-emblem"><ClientIcon name="lock" /></span><span class="qac-eyebrow">A FRESH KEY</span><h2 id="qac-password-dialog-title">{{ ct('准备换一把新钥匙？') }}</h2><p>{{ ct('修改成功后，此账号的所有登录和未使用的密码重置链接都会失效。请使用新密码重新登录。') }}</p><p>{{ ct('仅修改密码，已有会话与作品会保留。') }}</p><div class="qac-dialog-actions"><button type="button" :disabled="passwordSaving || sessionBusy" @click="closePasswordReview">{{ ct('返回检查') }}</button><button type="button" class="qac-primary" :disabled="passwordSaving || sessionBusy" @click="changePassword"><span v-if="passwordSaving" class="qac-spinner"></span>{{ passwordSaving ? ct('正在提交') : ct('修改并重新登录') }}</button></div></dialog>
  </div>
</template>

<script setup>
import {currentLang} from '../../i18n/index.js';
import {accountText} from '../../i18n/account-messages.js';
const ct=(key,params)=>accountText(currentLang.value,key,params);
import { computed, nextTick, onBeforeUnmount, onMounted, reactive, ref, watch } from 'vue';
import { useRoute } from 'vue-router';
import {usePersonalProfile} from '../../composables/usePersonalProfile.js';
import { api } from '../../api/client.js';
import { useAuth } from '../../stores/auth.js';
import { useAppearance } from '../../stores/appearance.js';
import { ACCOUNT_AVATARS, accountAvatar, accountDate as baseAccountDate, loginDevice as baseLoginDevice, passwordProblem } from '../../lib/account-profile.js';
import AccountAvatar from './AccountAvatar.vue';
import ProfilePhotoPicker from './ProfilePhotoPicker.vue';
import ClientIcon from '../reference/ClientIcon.vue';
import BrandLoader from './BrandLoader.vue';
import EmailVerificationCard from '../auth/EmailVerificationCard.vue';
import './account-studio.css';
import AccountSessionsCard from './AccountSessionsCard.vue';
const auth = useAuth(), appearance = useAppearance();
const accountDate=value=>baseAccountDate(value,currentLang.value),loginDevice=value=>baseLoginDevice(value,currentLang.value);
const sessionBusy=ref(false),cardTurned=ref(false),signaturePreview=ref(null),avatarBusy=ref(false),avatarEditing=ref(false);
function choosePhoto(value){draft.avatar=value;avatarTouched.value=true;}
async function turnCard(){cardTurned.value=!cardTurned.value;await nextTick();if(cardTurned.value)signaturePreview.value?.focus();}
const route = useRoute();
const emailCode=ref(''),emailReady=ref(false);
function emailVerified(at){if(profile.value&&profile.value.id===auth.user?.id){profile.value={...profile.value,emailVerifiedAt:at};auth.user.emailVerifiedAt=at;}}
const emailPolicyAbort=new AbortController();let emailPolicyAlive=true;
onMounted(async()=>{try{const row=await api.get('/auth/registration-policy',{signal:emailPolicyAbort.signal,retry:false});if(emailPolicyAlive)emailReady.value=!!row.emailDeliveryReady;}catch{}});
onBeforeUnmount(()=>{emailPolicyAlive=false;emailPolicyAbort.abort();});
const sections = [{id:'profile',title:'创作身份',icon:'user',number:'01'},{id:'security',title:'登录与密码',icon:'lock',number:'02'},{id:'start',title:'开始创作',icon:'star',number:'03'}];
const startSteps = [{number:'01 / CHAT',title:'聊清楚一个想法',description:'选择合适的模型，把问题、文档或图片交给你的搭档。',path:'/chat',icon:'chat'},{number:'02 / CREATE',title:'把脑海里的画面画出来',description:'从一段描述开始，在绘画工作台调整画面与参数。',path:'/painting',icon:'image'},{number:'03 / DISCOVER',title:'遇见不同专长的搭档',description:'去应用中心，挑一位适合眼前任务的 AI 助手。',path:'/apps',icon:'apps'}];
const section=ref('profile'),sectionNavigation=ref(null),tabButtons=[];
const password=reactive({old:'',next:'',confirm:''}),passwordSaving=ref(false),passwordError=ref(''),showPasswords=ref(false),passwordDialog=ref(null);
const {profile,draft,loading,loadError,profileSaving,profileNote,profileNoteKind,profileUncertain,avatarTouched,nameProblem,signatureProblem,dirty,loadProfile,saveProfile,confirmProfile,applyProfile,resetProfile}=usePersonalProfile({auth,blocked:()=>sessionBusy.value||passwordSaving.value||avatarBusy.value||avatarEditing.value});
const loginRows=ref([]),logsLoading=ref(false),logsError=ref(''),logPage=ref(1),logTotal=ref(0),logPageSize=4,revealNetwork=ref(false);
let alive=true,logsRequest=null,writeRequest=null,logVersion=0;
const current=stamp=>alive&&auth.isLoggedIn&&auth.user?.id===stamp.id&&auth.identityRevision===stamp.revision;
const stamp=()=>({id:auth.user?.id,revision:auth.identityRevision});
function clearPasswords(){password.old=password.next=password.confirm='';showPasswords.value=false;}
async function loadLogs(page = 1) {
  logsRequest?.abort(); const request = new AbortController(), owner = stamp(), version = ++logVersion; logsRequest = request; logsLoading.value = true; logsError.value = '';
  try { const data = await api.get('/users/logins?page=' + page + '&pageSize=' + logPageSize,{signal:request.signal,retry:false}); if (!current(owner) || request.signal.aborted || version !== logVersion) return; loginRows.value = data.items; logTotal.value=data.total; logPage.value=data.page; }
  catch (error) { if (current(owner) && !request.signal.aborted && version===logVersion) logsError.value=error?.message || '暂时无法读取登录记录。'; }
  finally { if (current(owner) && version===logVersion) logsLoading.value=false; }
}
function chooseSection(value) { if (!sections.some(x=>x.id===value) || passwordSaving.value) return; if (section.value==='security' && value!=='security') { clearPasswords(); passwordError.value=''; } section.value=value; if (value==='security' && !loginRows.value.length && !logsLoading.value) loadLogs(); }
async function openSection(value) { chooseSection(value); await nextTick(); sectionNavigation.value?.scrollIntoView?.({block:'start',behavior:appearance.motion && !window.matchMedia('(prefers-reduced-motion: reduce)').matches ? 'smooth' : 'instant'}); }
async function tabKey(event,index) { const moves={ArrowRight:(index+1)%3,ArrowLeft:(index+2)%3,Home:0,End:2}; if (!(event.key in moves)) return; event.preventDefault(); await openSection(sections[moves[event.key]].id); await nextTick(); tabButtons[moves[event.key]]?.focus(); }
function reviewPassword() { passwordError.value=passwordProblem(password.old,password.next,password.confirm,true,profile.value?.role === 'ADMIN'); if (passwordError.value || profileSaving.value || passwordSaving.value || sessionBusy.value) return; passwordDialog.value?.showModal(); }
function closePasswordReview() { if (passwordSaving.value) return; passwordDialog.value?.close(); }
function cancelPasswordReview(event) { if (passwordSaving.value) event.preventDefault(); }
async function changePassword() {
  if (passwordSaving.value || sessionBusy.value || passwordProblem(password.old,password.next,password.confirm,true,profile.value?.role === 'ADMIN')) return;
  const owner=stamp(), request=new AbortController(); writeRequest=request; passwordSaving.value=true; passwordError.value='';
  try { await api.post('/users/password',{oldPassword:password.old,newPassword:password.next},{signal:request.signal,retry:false}); if (current(owner)) auth.clearLocal('password-changed'); }
  catch (error) { if (!current(owner) || request.signal.aborted) return; if (!error?.status || error.status>=500) auth.clearLocal('password-unknown'); else passwordError.value=error?.message || '密码暂未修改，请检查后重试。'; }
  finally { if (current(owner)) { clearPasswords(); passwordDialog.value?.close(); passwordSaving.value=false; } }
}
watch(()=>auth.identityRevision,()=>{logsRequest?.abort();writeRequest?.abort();clearPasswords();passwordDialog.value?.close();section.value='profile';cardTurned.value=false;resetProfile();loginRows.value=[];revealNetwork.value=false;logsLoading.value=false;logsError.value='';logTotal.value=0;logPage.value=1;logVersion++;passwordSaving.value=false;passwordError.value='';if(auth.isLoggedIn)loadProfile();});
watch(() => route.query.section, value => { if (sections.some(item => item.id === value)) openSection(value); });
onMounted(async () => { const owner = stamp(); await loadProfile(); if (current(owner) && sections.some(item => item.id === route.query.section)) openSection(route.query.section); });
onBeforeUnmount(()=>{alive=false;logsRequest?.abort();writeRequest?.abort();clearPasswords();passwordDialog.value?.close();});
</script>
